13: class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
14:   static final _tween = Tween<double>(begin: 0.25, end: 1);
15: 
16:   late Future<List<NewsModel>> _newsListFuture;
17: 
18:   late final AnimationController _scaleController;
19:   late final Animation<double> _scaleAnimation;
20: 
21:   @override
22:   void initState() {
23:     super.initState();
24:     _initAnimation();
25:     _initData();
26:   }
27: 
28:   @override
29:   void dispose() {
30:     _scaleController.dispose();
31:     super.dispose();
32:   }
33: 
34:   void _initAnimation() {
35:     _scaleController = AnimationController(
36:       vsync: this,
37:       duration: Duration(milliseconds: 200),
38:     );
39:     _scaleAnimation = _tween.animate(_scaleController);
40:   }
41: 
42:   void _initData() {
43:     final newsRepository = context.read<NewsRepository>();
44: 
45:     _newsListFuture = newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((List<NewsModel> value) {
46: 
47:       _scaleController.forward(); // запускаем анимацию
48: 
49:       return value;
50:     });
51:   }
52: 
53:   @override
54:   Widget build(BuildContext context) {
55:     return Scaffold(
56:       appBar: AppBar(title: Text(context.loc.news)),
57:       body: FutureBuilder<List<NewsModel>>(
58:         future: _newsListFuture,
59:         builder: (BuildContext context, AsyncSnapshot<List<NewsModel>> snapshot) {
60:           final List<NewsModel>? data = snapshot.data;
61:           if (data == null) return const SizedBox.shrink();
62: 
63:           return ScaleTransition(
64:             scale: _scaleAnimation,
65:             child: ListView.builder(
66:               itemCount: data.length,
67:               itemBuilder: (BuildContext context, int index) {
68:                 final NewsModel news = data[index];
69: 
70:                 return Padding(
71:                   key: ValueKey(news.link),
72:                   padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
73:                   child: NewsCard(model: news),
74:                 );
75:               },
76:               padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
77:             ),
78:           );
79:         },
80:       ),
81:     );
82:   }
83: }

