5: 
6: class LoginPage extends StatefulWidget {
7:   const LoginPage({super.key});
8: 
9:   @override
10:   State<LoginPage> createState() => _LoginPageState();
11: }
12: 
13: class _LoginPageState extends State<LoginPage> with SingleTickerProviderStateMixin {
14:   late final AnimationController _controller;
15: 
16:   @override
17:   void initState() {
18:     super.initState();
19:     _initAnimation();
20:   }
21: 
22:   @override
23:   void dispose() {
24:     _controller.dispose();
25:     super.dispose();
26:   }
27: 
28:   void _initAnimation() {
29:     _controller = AnimationController(
30:       duration: const Duration(seconds: 2),
31:       vsync: this,
32:     )..repeat();
33:   }
34: 
35:   @override
36:   Widget build(BuildContext context) {
37:     return Scaffold(
38:       body: Center(
39:         child: AnimatedBuilder(
40:           animation: _controller,
41:           child: ElevatedButton(
42:             onPressed: () => context.read<SettingsRepository>().setToken(_generateRandomToken()),
43:             child: Text(
44:               context.loc.login,
45:               style: context.fonts.regular14,
46:             ),
47:           ),
48:           builder: (BuildContext context, Widget? child) {
49:             return Transform.rotate(angle: _controller.value * 2 * pi, child: child);
50:           },
51:         ),
52:       ),
53:     );
54:   }
55: }
56: 
57: String _generateRandomToken([int length = 32]) {
58:   const String chars = 'AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz0123456789';
59:   final Random random = Random();
60: 
61:   return String.fromCharCodes(
62:     Iterable.generate(
63:       length,
64:       (_) => chars.codeUnitAt(random.nextInt(chars.length)),
65:     ),
66:   );
67: }

