class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  int _selectedIndex = 0;

  final GlobalKey<CurrencyListPageState> _currencyListKey = GlobalKey();
  final GlobalKey<NewsListPageState> _newsListKey = GlobalKey();

  static const List<Widget> _pages = <Widget>[
    CurrencyListPage(key: ValueKey('currency')),
    NewsListPage(key: ValueKey('news')),
    ProfilePage(),
  ];

  void _onItemTapped(int index) {
    setState(() {
      _selectedIndex = index;
    });
  }

  Future<void> _refreshAll() async {
    final List<Future<void>> futures = <Future<void>>[];

    if (_selectedIndex == 0) {
      futures.add(_currencyListKey.currentState!.refresh());
    } else if (_selectedIndex == 1) {
      futures.add(_newsListKey.currentState!.refresh());
    }

    // Обновляем неактивную вкладку тоже, чтобы данные были свежими
    if (_selectedIndex != 0) {
      futures.add(_currencyListKey.currentState!.refresh());
    }
    if (_selectedIndex != 1) {
      futures.add(_newsListKey.currentState!.refresh());
    }

    await Future.wait(futures);
  }

  @override
  Widget build(BuildContext context) {
    final Widget currentPage = _pages[_selectedIndex];
    final AppLocalizations loc = context.loc;

    return Scaffold(
      body: currentPage,
      floatingActionButton: FloatingActionButton(
        onPressed: _refreshAll,
        child: const Icon(Icons.refresh),
        tooltip: loc.refreshAll,
      ),
      bottomNavigationBar: Container(
        decoration: BoxDecoration(
          boxShadow: <BoxShadow>[
            BoxShadow(
              color: context.colors.bottomNavBarShadow,
              blurRadius: 25,
              offset: Offset(0.0, 0.75),
